PREFIX brick: <https://brickschema.org/schema/Brick#>
PREFIX bldg: <http://buildgraph.org/BG_medium_office_2004_0000#>
PREFIX ref: <https://brickschema.org/schema/Brick/ref#>
SELECT ?sensor ?cls ?tsid WHERE {
  ?sensor brick:hasLocation bldg:Zone_F3_Z02 .
  ?sensor a ?cls .
  OPTIONAL { ?sensor ref:hasTimeseriesId ?tsid . ?tsid a brick:ref:TimeseriesReference }
}

